def transform(grid):
    # Tiles are 2x2 blocks (color 1) and L-triominoes. Find a disjoint
    # tiling of the occupied cells, preferring squares when possible.
    cells = {(r, c) for r in range(len(grid)) for c in range(len(grid[0]))
             if grid[r][c] == 8}
    tiles = []
    for r in range(len(grid) - 1):
        for c in range(len(grid[0]) - 1):
            box = {(r+i, c+j) for i in range(2) for j in range(2)}
            if box <= cells:
                tiles.append((box, 1))
            for missing in box:
                tri = box - {missing}
                if tri <= cells:
                    # Color is determined by the missing corner.
                    color = {(r,c): 2, (r,c+1): 4,
                             (r+1,c): 3, (r+1,c+1): 2}[missing]
                    tiles.append((tri, color))

    # Prefer larger square tiles, then use a consistent ordering.
    tiles.sort(key=lambda t: (-len(t[0]), min(t[0]), t[1]))

    def cover(left):
        if not left:
            return []
        p = min(left)
        for shape, color in tiles:
            if p in shape and shape <= left:
                rest = cover(left - shape)
                if rest is not None:
                    return [(shape, color)] + rest
        return None

    chosen = cover(cells)
    out = [[0] * len(grid[0]) for _ in grid]
    if chosen is None:
        return out
    for shape, color in chosen:
        for r, c in shape:
            out[r][c] = color
    return out
